runtime.provision:
set -e
PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" "$STACK_INSTALL_DIR/bin/psql" -h "$STACK_SOCKET_DIR" -p "$STACK_PORT" -U stack_admin -d postgres -X -w -q -v ON_ERROR_STOP=1 -v ECHO=none <<'SQL'
SET log_statement = 'none';
SET log_min_error_statement = 'panic';
SET log_min_duration_statement = -1;
SET log_min_duration_sample = -1;
SET log_transaction_sample_rate = 0;
SET password_encryption = 'scram-sha-256';
REVOKE ALL ON DATABASE postgres, template0, template1 FROM PUBLIC;
\getenv group_password DB_PASSWORD
\getenv group_name STACK_GROUP
SELECT format('CREATE ROLE %I LOGIN', :'group_name')
  WHERE NOT EXISTS (SELECT FROM pg_roles WHERE rolname = :'group_name')\gexec
ALTER ROLE :"group_name" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD :'group_password';
SELECT format('CREATE DATABASE %I OWNER %I ALLOW_CONNECTIONS false', :'group_name', :'group_name')
  WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = :'group_name')\gexec
REVOKE CONNECT ON DATABASE :"group_name" FROM PUBLIC;
ALTER DATABASE :"group_name" ALLOW_CONNECTIONS true;
SQL

